package org.eclipse.amp.amf.examples.escape;

import org.eclipse.draw2d.ColorConstants;
import org.eclipse.draw2d.Graphics;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Display;

import org.ascape.model.Agent;
import org.ascape.model.CellOccupant;
import org.ascape.model.HostCell;

import org.ascape.util.vis.DrawFeature;

/**
 * Simple Draw Java Implementation.
 * 
 * Generated by AMF for model: WikiExample.metaabm in project: org.eclipse.amp.amf.examples.escape 
 */

public class SimpleDrawGraphics extends DrawFeature {

	enum Shapes {
		rectangle, oval, marker
	};

	Shapes shape = Shapes.rectangle;

	public void draw(Graphics g, Object object, int width, int height) {

		HostCell definitionCell = (HostCell) object;
		if (definitionCell.getOccupant() instanceof Individual) {
			Individual definition = (Individual) definitionCell.getOccupant();
			Individual individualRule = definition;

			Color individualRuleColorRGB_WealthUnitUnit_ = new Color(Display
					.getCurrent(), (int) (individualRule.getWealth() * 255),
					(int) (1 * 255), (int) (1 * 255));
			g.setForegroundColor(individualRuleColorRGB_WealthUnitUnit_);
			g.setBackgroundColor(individualRuleColorRGB_WealthUnitUnit_);
			shape = shape.oval;
			if (shape == Shapes.oval) {
				g.fillOval(0, 0, width, height);
			} else if (shape == Shapes.marker) {
				int d = (int) (width * .25 - 1);
				int d2 = (int) (width * .5 - 1);
				g.fillOval(d, d, d2, d2);
			} else if (shape == Shapes.rectangle) {
				g.fillRectangle(0, 0, width, height);
			}

		}
	}
}
